const prepared=[];
for(const [file,ops] of changes){
 const dest=path.join(root,file);let source=fs.readFileSync(dest,'utf8').replace(/\r\n/g,'\n');
 for(const [before,after] of ops){const needle=before.replace(/\r\n/g,'\n');if(source.split(needle).length!==2)throw Error('Unexpected source layout: '+file);source=source.replace(needle,after.replace(/\r\n/g,'\n'));}
 prepared.push([dest,source]);
}
for(const [dest,source] of prepared)fs.writeFileSync(dest,source);
